//! Execution of the queries generated by pgweave (PLAN.md D8, P5).
//!
//! Generated code describes each query with a [`Query`] (positional SQL,
//! parameter types) and calls the function matching its cardinality:
//! [`fetch_one`], [`fetch_optional`], [`fetch_all`] or [`execute`].
//!
//! - Parameter types known at compile time (built-in types, fixed OID):
//!   `query_typed`, no prepare round trip.
//! - Project-defined type (enum, domain…): its OID only exists in the
//!   database; the query is prepared and the server fixes the types.
//! - Rows decoded by column index, into generated structs.
//!
//! Any client works: [`GenericClient`] covers client, transaction and
//! pooled connection.

use std::fmt;

#[cfg(feature = "trace")]
pub mod trace;

pub use futures_util;
pub use tokio;
pub use tokio_postgres::types::{self, FromSql, ToSql, Type};
pub use tokio_postgres::{self, GenericClient, Row};

/// A generated query.
#[derive(Debug, Clone, Copy)]
pub struct Query {
    pub name: &'static str,
    /// SQL sent to the server (positional parameters).
    pub sql: &'static str,
    /// OID of each parameter; `None` if one of them is a project type,
    /// whose OID is only known in the database.
    pub param_oids: Option<&'static [u32]>,
}

/// Parameter bound to a query.
pub type Param<'a> = &'a (dyn ToSql + Sync);

#[derive(Debug)]
pub enum Error {
    /// Error returned by PostgreSQL or by the connection.
    Db {
        query: &'static str,
        source: tokio_postgres::Error,
    },
    /// Row count contrary to the query's cardinality.
    RowCount {
        query: &'static str,
        expected: &'static str,
        got: usize,
    },
    /// Column value not decodable into the generated type.
    Decode {
        query: &'static str,
        source: tokio_postgres::Error,
    },
    /// Reading the data of a `COPY`.
    Io {
        query: &'static str,
        source: std::io::Error,
    },
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::Db { query, source } => write!(f, "query `{query}`: {source}"),
            Error::RowCount {
                query,
                expected,
                got,
            } => write!(
                f,
                "query `{query}`: expected {expected}, {got} row(s) returned"
            ),
            Error::Decode { query, source } => {
                write!(f, "query `{query}`: decoding a row: {source}")
            }
            Error::Io { query, source } => {
                write!(f, "query `{query}`: reading data: {source}")
            }
        }
    }
}

impl std::error::Error for Error {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Error::Db { source, .. } | Error::Decode { source, .. } => Some(source),
            Error::Io { source, .. } => Some(source),
            Error::RowCount { .. } => None,
        }
    }
}

/// Decoding of a row into the generated struct.
pub type Decode<T> = fn(&Row) -> Result<T, tokio_postgres::Error>;

/// Parameter types, if all of them are known to `tokio-postgres`.
fn static_types(q: &Query) -> Option<Vec<Type>> {
    q.param_oids?
        .iter()
        .map(|oid| Type::from_oid(*oid))
        .collect()
}

async fn rows<C: GenericClient + ?Sized>(
    client: &C,
    q: &Query,
    params: &[Param<'_>],
) -> Result<Vec<Row>, Error> {
    let db = |source| Error::Db {
        query: q.name,
        source,
    };
    match static_types(q) {
        Some(types) => {
            let typed: Vec<(Param<'_>, Type)> = params.iter().copied().zip(types).collect();
            client.query_typed(q.sql, &typed).await.map_err(db)
        }
        None => client.query(q.sql, params).await.map_err(db),
    }
}

fn decode<T>(q: &Query, row: &Row, f: Decode<T>) -> Result<T, Error> {
    f(row).map_err(|source| Error::Decode {
        query: q.name,
        source,
    })
}

/// All rows.
pub async fn fetch_all<C: GenericClient + ?Sized, T>(
    client: &C,
    q: &Query,
    params: &[Param<'_>],
    f: Decode<T>,
) -> Result<Vec<T>, Error> {
    rows(client, q, params)
        .await?
        .iter()
        .map(|r| decode(q, r, f))
        .collect()
}

/// Zero or one row; more than one is an error.
pub async fn fetch_optional<C: GenericClient + ?Sized, T>(
    client: &C,
    q: &Query,
    params: &[Param<'_>],
    f: Decode<T>,
) -> Result<Option<T>, Error> {
    match rows(client, q, params).await?.as_slice() {
        [] => Ok(None),
        [row] => decode(q, row, f).map(Some),
        more => Err(Error::RowCount {
            query: q.name,
            expected: "at most one row",
            got: more.len(),
        }),
    }
}

/// Exactly one row.
pub async fn fetch_one<C: GenericClient + ?Sized, T>(
    client: &C,
    q: &Query,
    params: &[Param<'_>],
    f: Decode<T>,
) -> Result<T, Error> {
    match rows(client, q, params).await?.as_slice() {
        [row] => decode(q, row, f),
        other => Err(Error::RowCount {
            query: q.name,
            expected: "exactly one row",
            got: other.len(),
        }),
    }
}

/// Statement returning no rows: number of affected rows.
pub async fn execute<C: GenericClient + ?Sized>(
    client: &C,
    q: &Query,
    params: &[Param<'_>],
) -> Result<u64, Error> {
    let db = |source| Error::Db {
        query: q.name,
        source,
    };
    match static_types(q) {
        Some(types) => {
            let typed: Vec<(Param<'_>, Type)> = params.iter().copied().zip(types).collect();
            client.execute_typed(q.sql, &typed).await.map_err(db)
        }
        None => client.execute(q.sql, params).await.map_err(db),
    }
}

/// PostgreSQL enum seen as its labels: text encoding and decoding
/// (the binary form of an enum is its label). Implemented by generated code.
pub trait PgEnum: Sized {
    /// Type name in the database (`pg_type.typname`).
    const TYPE_NAME: &'static str;
    fn label(&self) -> &'static str;
    fn from_label(label: &str) -> Option<Self>;
}

/// Decoding of a generated enum.
pub fn enum_from_sql<E: PgEnum>(raw: &[u8]) -> Result<E, Box<dyn std::error::Error + Sync + Send>> {
    let label = std::str::from_utf8(raw)?;
    E::from_label(label)
        .ok_or_else(|| format!("unknown label for {}: {label:?}", E::TYPE_NAME).into())
}

/// Encoding of a generated enum.
pub fn enum_to_sql<E: PgEnum>(
    e: &E,
    out: &mut types::private::BytesMut,
) -> Result<types::IsNull, Box<dyn std::error::Error + Sync + Send>> {
    out.extend_from_slice(e.label().as_bytes());
    Ok(types::IsNull::No)
}

// ── Inline queries (`query!`) ─────────────────────────────────────────────────

/// Value bound to a parameter of an inline query, owned by it.
pub type Bound<'a> = Box<dyn ToSql + Sync + 'a>;

/// Binds a value to a parameter (code generated by `query!`).
pub fn bind<'a, T: ToSql + Sync + 'a>(v: T) -> Bound<'a> {
    Box::new(v)
}

/// Cardinality markers of an inline query.
pub mod cardinality {
    /// Exactly one row.
    pub struct One;
    /// Zero or one row.
    pub struct Optional;
    /// Any number of rows.
    pub struct Many;
    /// No rows returned.
    pub struct NoRows;
}

/// Inline query ready to run: its bound parameters, its row, its
/// cardinality `K`. `fetch` returns what the cardinality promises; the
/// narrower variants are contracts checked at run time.
pub struct Inline<'a, T, K> {
    query: &'static Query,
    params: Vec<Bound<'a>>,
    decode: Decode<T>,
    _cardinality: std::marker::PhantomData<K>,
}

impl<'a, T, K> Inline<'a, T, K> {
    pub fn new(query: &'static Query, params: Vec<Bound<'a>>, decode: Decode<T>) -> Self {
        Inline {
            query,
            params,
            decode,
            _cardinality: std::marker::PhantomData,
        }
    }

    fn params(&self) -> Vec<Param<'_>> {
        self.params
            .iter()
            .map(|b| b.as_ref() as Param<'_>)
            .collect()
    }
}

impl<T> Inline<'_, T, cardinality::One> {
    pub async fn fetch<C: GenericClient + ?Sized>(self, client: &C) -> Result<T, Error> {
        fetch_one(client, self.query, &self.params(), self.decode).await
    }
}

impl<T> Inline<'_, T, cardinality::Optional> {
    pub async fn fetch<C: GenericClient + ?Sized>(self, client: &C) -> Result<Option<T>, Error> {
        fetch_optional(client, self.query, &self.params(), self.decode).await
    }

    /// Exactly one row expected: absence is an error.
    pub async fn fetch_one<C: GenericClient + ?Sized>(self, client: &C) -> Result<T, Error> {
        fetch_one(client, self.query, &self.params(), self.decode).await
    }
}

impl<T> Inline<'_, T, cardinality::Many> {
    pub async fn fetch<C: GenericClient + ?Sized>(self, client: &C) -> Result<Vec<T>, Error> {
        fetch_all(client, self.query, &self.params(), self.decode).await
    }

    /// At most one row expected.
    pub async fn fetch_optional<C: GenericClient + ?Sized>(
        self,
        client: &C,
    ) -> Result<Option<T>, Error> {
        fetch_optional(client, self.query, &self.params(), self.decode).await
    }

    /// Exactly one row expected.
    pub async fn fetch_one<C: GenericClient + ?Sized>(self, client: &C) -> Result<T, Error> {
        fetch_one(client, self.query, &self.params(), self.decode).await
    }
}

impl Inline<'_, (), cardinality::NoRows> {
    /// Number of affected rows.
    pub async fn execute<C: GenericClient + ?Sized>(self, client: &C) -> Result<u64, Error> {
        execute(client, self.query, &self.params()).await
    }
}

// ── COPY … FROM STDIN ─────────────────────────────────────────────────────────

/// Client able to run `COPY … FROM STDIN`: bare client or transaction
/// (`GenericClient` does not expose it).
pub trait CopyClient: GenericClient {
    fn copy_in_sink(
        &self,
        sql: &str,
    ) -> impl std::future::Future<
        Output = Result<tokio_postgres::CopyInSink<bytes::Bytes>, tokio_postgres::Error>,
    > + Send;
}

impl CopyClient for tokio_postgres::Client {
    async fn copy_in_sink(
        &self,
        sql: &str,
    ) -> Result<tokio_postgres::CopyInSink<bytes::Bytes>, tokio_postgres::Error> {
        self.copy_in(sql).await
    }
}

impl CopyClient for tokio_postgres::Transaction<'_> {
    async fn copy_in_sink(
        &self,
        sql: &str,
    ) -> Result<tokio_postgres::CopyInSink<bytes::Bytes>, tokio_postgres::Error> {
        self.copy_in(sql).await
    }
}

/// A generated `COPY … FROM STDIN`.
#[derive(Debug, Clone, Copy)]
pub struct CopyIn {
    pub name: &'static str,
    pub sql: &'static str,
    /// Target table and columns, quoted, to look up their types.
    pub table: &'static str,
    pub columns: &'static str,
    /// Column OIDs, `None` if one of them has a project type.
    pub column_oids: Option<&'static [u32]>,
}

/// Typed binary writing of a `COPY`: one row per call to [`write`].
///
/// [`write`]: BinaryCopy::write
pub struct BinaryCopy {
    copy: &'static CopyIn,
    writer: std::pin::Pin<Box<tokio_postgres::binary_copy::BinaryCopyInWriter>>,
}

impl BinaryCopy {
    /// Opens the `COPY`; column types are those of the catalog
    /// (fixed OIDs) or, for a project type, those of the database.
    pub async fn open<C: CopyClient + ?Sized>(
        client: &C,
        copy: &'static CopyIn,
    ) -> Result<Self, Error> {
        let db = |source| Error::Db {
            query: copy.name,
            source,
        };
        let types: Vec<Type> = match copy.column_oids.and_then(|oids| {
            oids.iter()
                .map(|o| Type::from_oid(*o))
                .collect::<Option<Vec<_>>>()
        }) {
            Some(t) => t,
            None => client
                .prepare(&format!(
                    "SELECT {} FROM {} LIMIT 0",
                    copy.columns, copy.table
                ))
                .await
                .map_err(db)?
                .columns()
                .iter()
                .map(|c| c.type_().clone())
                .collect(),
        };
        let sink = client.copy_in_sink(copy.sql).await.map_err(db)?;
        Ok(BinaryCopy {
            copy,
            writer: Box::pin(tokio_postgres::binary_copy::BinaryCopyInWriter::new(
                sink, &types,
            )),
        })
    }

    pub async fn write(&mut self, values: &[Param<'_>]) -> Result<(), Error> {
        self.writer
            .as_mut()
            .write(values)
            .await
            .map_err(|source| Error::Db {
                query: self.copy.name,
                source,
            })
    }

    /// Finishes the `COPY`: number of copied rows.
    pub async fn finish(mut self) -> Result<u64, Error> {
        self.writer
            .as_mut()
            .finish()
            .await
            .map_err(|source| Error::Db {
                query: self.copy.name,
                source,
            })
    }
}

/// `COPY` in text or CSV format: the bytes of `reader`, as is, in
/// chunks. Returns the number of copied rows.
pub async fn copy_in_stream<C, R>(
    client: &C,
    copy: &'static CopyIn,
    mut reader: R,
) -> Result<u64, Error>
where
    C: CopyClient + ?Sized,
    R: tokio::io::AsyncRead + Unpin,
{
    use futures_util::SinkExt;
    use tokio::io::AsyncReadExt;
    let db = |source| Error::Db {
        query: copy.name,
        source,
    };
    let sink = client.copy_in_sink(copy.sql).await.map_err(db)?;
    let mut sink = Box::pin(sink);
    let mut buf = vec![0u8; 64 * 1024];
    loop {
        let n = reader.read(&mut buf).await.map_err(|e| Error::Io {
            query: copy.name,
            source: e,
        })?;
        if n == 0 {
            break;
        }
        sink.send(bytes::Bytes::copy_from_slice(&buf[..n]))
            .await
            .map_err(db)?;
    }
    sink.as_mut().finish().await.map_err(db)
}

// ── Row streams ───────────────────────────────────────────────────────────────

/// Rows decoded as they arrive, without loading everything in memory.
pub async fn stream<C: GenericClient + ?Sized, T>(
    client: &C,
    q: &'static Query,
    params: &[Param<'_>],
    f: Decode<T>,
) -> Result<impl futures_util::Stream<Item = Result<T, Error>> + Send + use<T, C>, Error>
where
    T: Send + 'static,
{
    use futures_util::StreamExt;
    let db = |source| Error::Db {
        query: q.name,
        source,
    };
    let rows = match static_types(q) {
        Some(types) => client
            .query_typed_raw(q.sql, params.iter().copied().zip(types))
            .await
            .map_err(db)?,
        None => client
            .query_raw(q.sql, params.iter().copied())
            .await
            .map_err(db)?,
    };
    let name = q.name;
    Ok(rows.map(move |r| match r {
        Ok(row) => f(&row).map_err(|source| Error::Decode {
            query: name,
            source,
        }),
        Err(source) => Err(Error::Db {
            query: name,
            source,
        }),
    }))
}

// ── Domains ───────────────────────────────────────────────────────────────────

/// Value passed to a domain-typed parameter. A query prepared by the
/// server announces the domain itself (`cents`), which the base Rust types
/// reject; the value is encoded with the domain's base type.
#[derive(Debug, Clone, Copy)]
pub struct Domain<T>(pub T);

impl<T: ToSql> ToSql for Domain<T> {
    fn to_sql(
        &self,
        ty: &Type,
        out: &mut types::private::BytesMut,
    ) -> Result<types::IsNull, Box<dyn std::error::Error + Sync + Send>> {
        match ty.kind() {
            types::Kind::Domain(base) => self.0.to_sql(base, out),
            _ => self.0.to_sql(ty, out),
        }
    }

    fn accepts(ty: &Type) -> bool {
        match ty.kind() {
            types::Kind::Domain(base) => T::accepts(base),
            _ => T::accepts(ty),
        }
    }

    types::to_sql_checked!();
}

/// String equality evaluated at compile time: checking a reused row
/// (`sql!`, `-> Path`) compares column descriptions in constant
/// assertions.
#[doc(hidden)]
pub const fn str_eq(a: &str, b: &str) -> bool {
    let (a, b) = (a.as_bytes(), b.as_bytes());
    if a.len() != b.len() {
        return false;
    }
    let mut i = 0;
    while i < a.len() {
        if a[i] != b[i] {
            return false;
        }
        i += 1;
    }
    true
}
